        <section class="rounded-xl bg-white border p-4"><div class="flex justify-between"><h2 class="text-lg font-bold">Planned versus actual consumption</h2>@if(auth()->user()->hasPermission('manage_feed_issues'))<a class="underline text-emerald-700" href="{{ route('feed.issues.create') }}">Record feeding</a>@endif</div><p class="text-sm text-slate-500">Feed is recorded per stage; one saved daily target per stage and feed type. Older group deliveries match a stage or location filter when their saved population includes it. Unknown means the original issue has no reliable plan. Variance is not automatically classified as wastage or underfeeding.</p>@unless(is_numeric($varianceThreshold))<p class="mt-2 rounded-lg bg-amber-50 p-2 text-sm text-amber-900">No variance alert is set, so big differences between ration and feed given are not flagged. @if(auth()->user()->hasPermission('manage_feed_production'))<a href="{{ route('feed-setup.index') }}#settings" class="font-semibold underline">Set a variance alert</a>.@else Ask a farm manager to set one in Feed Setup.@endif</p>@endunless<div class="overflow-x-auto"><table class="data-table"><thead><tr>@foreach(['Date','Fed to','Feed / stages','Planned kg','Actual kg','Variance kg','Variance %'] as $label)<th>{{ $label }}</th>@endforeach</tr></thead><tbody>
        @forelse($consumption as $row)<tr class="border-t {{ is_numeric($varianceThreshold) && $row['variance_percent'] !== null && abs($row['variance_percent']) >= $varianceThreshold ? 'bg-amber-50' : '' }}"><td>{{ $row['date'] }}</td><td>{{ $row['group'] }}@if(! empty($row['rooms']))<span class="block text-xs text-slate-500">{{ implode(', ', $row['rooms']) }}</span>@endif @if(is_numeric($varianceThreshold) && $row['variance_percent'] !== null && abs($row['variance_percent']) >= $varianceThreshold)<p class="font-semibold text-amber-700">Variance needs review</p>@endif
            @php $ids = $row['issue_ids'] ?? []; @endphp
            @if(count($ids) === 1)<a href="{{ route('feed.issues.show', $ids[0]) }}" class="text-xs font-semibold text-emerald-700 hover:underline">Open feeding</a>@elseif(count($ids) > 1)<a href="{{ route('feed.issues.index', ['date' => $row['date']]) }}" class="text-xs font-semibold text-emerald-700 hover:underline">View {{ count($ids) }} feedings</a>@endif</td><td>{{ $row['feed_type'] }}<br>{{ implode(', ', array_map(fn($stage)=>$stages[$stage]??$stage, $row['stages'])) }}</td>@foreach(['planned_kg','actual_kg','variance_kg','variance_percent'] as $field)<td>{{ $row[$field]===null?'Unknown':number_format($row[$field],2) }}</td>@endforeach</tr>@empty<tr><td colspan="7" class="p-6 text-slate-500">No feed issues recorded for this period and selection.</td></tr>@endforelse
        </tbody></table></div>
        <div class="mt-3"><x-pager :paginator="$consumption" label="rows" /></div></section>
